INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-hipertensi','mengenal-hipertensi-dan-cara-mengendalikannya','Mengenal Hipertensi dan Cara Mengendalikannya','ptm','Hipertensi adalah tekanan darah 140/90 mmHg atau lebih. Di Lampung, SKI 2023 menunjukkan 29,7% penduduk dewasa terukur hipertensi, tetapi hanya 7,9% yang terdiagnosis dokter.','Hipertensi sering disebut pembunuh senyap karena umumnya tidak bergejala. Seseorang dikatakan hipertensi bila tekanan darah sistolik 140 mmHg atau lebih, atau diastolik 90 mmHg atau lebih, pada pengukuran berulang.

Data Survei Kesehatan Indonesia (SKI) 2023 untuk Provinsi Lampung menunjukkan kesenjangan besar: prevalensi hipertensi berdasarkan pengukuran mencapai 29,7% pada penduduk usia 18 tahun ke atas, sedangkan yang terdiagnosis oleh dokter hanya 7,9%. Artinya, sebagian besar penderita belum mengetahui kondisinya.

Faktor risiko hipertensi meliputi konsumsi garam berlebih, kurang aktivitas fisik, merokok, kelebihan berat badan, dan riwayat keluarga. Kemenkes menganjurkan pembatasan garam tidak lebih dari 1 sendok teh (sekitar 5 gram) per hari, aktivitas fisik minimal 30 menit setiap hari, berhenti merokok, dan memeriksa tekanan darah secara berkala — misalnya di Posbindu PTM atau puskesmas.

Bila hasil pengukuran Anda berulang kali berada pada rentang hipertensi, periksalah ke puskesmas atau dokter. Penegakan diagnosis dan pengobatan adalah kewenangan tenaga kesehatan; jangan memulai, menghentikan, atau mengubah dosis obat tanpa konsultasi.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published', datetime('now'));
