VALUES ('src-art-hipertensi', 'Mengenal Hipertensi dan Cara Mengendalikannya', 'Kementerian Kesehatan RI', 'https://ayosehat.kemkes.go.id', 'Hipertensi adalah tekanan darah 140/90 mmHg atau lebih. Di Lampung, SKI 2023 menunjukkan 29,7% penduduk dewasa terukur hipertensi, tetapi hanya 7,9% yang terdiagnosis dokter. Hipertensi sering disebut pembunuh senyap karena umumnya tidak bergejala. Seseorang dikatakan hipertensi bila tekanan darah sistolik 140 mmHg atau lebih, atau diastolik 90 mmHg atau lebih, pada pengukuran berulang.

Data Survei Kesehatan Indonesia (SKI) 2023 untuk Provinsi Lampung menunjukkan kesenjangan besar: prevalensi hipertensi berdasarkan pengukuran mencapai 29,7% pada penduduk usia 18 tahun ke atas, sedangkan yang terdiagnosis oleh dokter hanya 7,9%. Artinya, sebagian besar penderita belum mengetahui kondisinya.

Faktor risiko hipertensi meliputi konsumsi garam berlebih, kurang aktivitas fisik, merokok, kelebihan berat badan, dan riwayat keluarga. Kemenkes menganjurkan pembatasan garam tidak lebih dari 1 sendok teh (sekitar 5 gram) per hari, aktivitas fisik minimal 30 menit setiap hari, berhenti merokok, dan memeriksa tekanan darah secara berkala — misalnya di Posbindu PTM atau puskesmas.

Bila hasil pengukuran Anda berulang kali berada pada rentang hipertensi, periksalah ke puskesmas atau dokter. Penegakan diagnosis dan pengobatan adalah kewenangan tenaga kesehatan; jangan memulai, menghentikan, atau mengubah dosis obat tanpa konsultasi.', 'ptm, skrining, pencegahan', 'active');
INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-isi-piringku','isi-piringku-pedoman-makan-seimbang','Isi Piringku: Pedoman Makan Seimbang','gizi','Isi Piringku adalah pedoman Kemenkes untuk sekali makan: setengah piring sayur dan buah, setengahnya makanan pokok dan lauk pauk, disertai air putih dan cuci tangan pakai sabun.','Isi Piringku adalah panduan visual Kementerian Kesehatan untuk mengatur porsi makan dalam satu piring pada setiap kali makan.

Komposisinya: setengah bagian piring diisi sayur dan buah-buahan (porsi sayur lebih banyak daripada buah), sedangkan setengah lainnya diisi makanan pokok dan lauk pauk (porsi makanan pokok lebih banyak daripada lauk). Pedoman ini dilengkapi anjuran minum air putih 8 gelas sehari, mencuci tangan pakai sabun, beraktivitas fisik 30 menit sehari, dan memantau berat badan.

Untuk mencegah penyakit tidak menular, batasi konsumsi gula, garam, dan lemak: gula maksimal 4 sendok makan, garam 1 sendok teh, dan lemak/minyak 5 sendok makan per orang per hari. Variasikan sumber pangan lokal — termasuk pangan khas Lampung seperti singkong, pisang, dan ikan air tawar — agar kebutuhan gizi terpenuhi tanpa harus mahal.

Pedoman ini adalah anjuran umum. Kebutuhan gizi khusus, misalnya pada ibu hamil, anak, lansia, atau penderita penyakit tertentu, perlu konsultasi dengan tenaga gizi di puskesmas.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published', datetime('now'));
-- referensi art-isi-piringku dimasukkan lewat edu_references pada migration 0014: [{"title": "Isi Piringku — pedoman gizi ...
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-isi-piringku', 'Isi Piringku: Pedoman Makan Seimbang', 'Kementerian Kesehatan RI', 'https://ayosehat.kemkes.go.id', 'Isi Piringku adalah pedoman Kemenkes untuk sekali makan: setengah piring sayur dan buah, setengahnya makanan pokok dan lauk pauk, disertai air putih dan cuci tangan pakai sabun. Isi Piringku adalah panduan visual Kementerian Kesehatan untuk mengatur porsi makan dalam satu piring pada setiap kali makan.

Komposisinya: setengah bagian piring diisi sayur dan buah-buahan (porsi sayur lebih banyak daripada buah), sedangkan setengah lainnya diisi makanan pokok dan lauk pauk (porsi makanan pokok lebih banyak daripada lauk). Pedoman ini dilengkapi anjuran minum air putih 8 gelas sehari, mencuci tangan pakai sabun, beraktivitas fisik 30 menit sehari, dan memantau berat badan.

Untuk mencegah penyakit tidak menular, batasi konsumsi gula, garam, dan lemak: gula maksimal 4 sendok makan, garam 1 sendok teh, dan lemak/minyak 5 sendok makan per orang per hari. Variasikan sumber pangan lokal — termasuk pangan khas Lampung seperti singkong, pisang, dan ikan air tawar — agar kebutuhan gizi terpenuhi tanpa harus mahal.

Pedoman ini adalah anjuran umum. Kebutuhan gizi khusus, misalnya pada ibu hamil, anak, lansia, atau penderita penyakit tertentu, perlu konsultasi dengan tenaga gizi di puskesmas.', 'gizi, skrining, pencegahan', 'active');
INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-skrining-posbindu','cek-kesehatan-dan-skrining-ptm-di-posbindu','Cek Kesehatan dan Skrining PTM di Posbindu','ptm','Posbindu PTM adalah pos pembinaan terpadu untuk deteksi dini faktor risiko penyakit tidak menular. Lampung memiliki 2.771 Posbindu menurut Profil Kesehatan 2023.','Penyakit tidak menular seperti hipertensi, diabetes, dan penyakit jantung umumnya berkembang tanpa gejala pada tahap awal. Deteksi dini melalui skrining berkala adalah cara paling efektif untuk mencegah komplikasi.

Posbindu PTM adalah kegiatan masyarakat untuk deteksi dini dan pemantauan faktor risiko PTM: pengukuran berat dan tinggi badan, tekanan darah, gula darah, serta konseling gaya hidup. Menurut Profil Kesehatan Provinsi Lampung 2023, terdapat 2.771 Posbindu PTM di Lampung. Selain Posbindu, skrining dapat dilakukan di puskesmas dan melalui program Cek Kesehatan Gratis Kemenkes yang berjalan sejak Februari 2025.

SIGERSEHAT membantu Anda melakukan skrining awal mandiri dan mencatat hasil pengukuran dari Posbindu atau puskesmas agar perkembangannya terpantau. Ingat: hasil skrining bukan diagnosis. Bila hasil Anda berada pada kategori sedang atau tinggi, tindaklanjuti dengan pemeriksaan di fasilitas kesehatan.','Dinas Kesehatan Provinsi Lampung','https://dinkes.lampungprov.go.id','published', datetime('now'));
-- referensi art-skrining-posbindu dimasukkan lewat edu_references pada migration 0014: [{"title": "Profil Kesehatan Provinsi La...
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-skrining-posbindu', 'Cek Kesehatan dan Skrining PTM di Posbindu', 'Dinas Kesehatan Provinsi Lampung', 'https://dinkes.lampungprov.go.id', 'Posbindu PTM adalah pos pembinaan terpadu untuk deteksi dini faktor risiko penyakit tidak menular. Lampung memiliki 2.771 Posbindu menurut Profil Kesehatan 2023. Penyakit tidak menular seperti hipertensi, diabetes, dan penyakit jantung umumnya berkembang tanpa gejala pada tahap awal. Deteksi dini melalui skrining berkala adalah cara paling efektif untuk mencegah komplikasi.

Posbindu PTM adalah kegiatan masyarakat untuk deteksi dini dan pemantauan faktor risiko PTM: pengukuran berat dan tinggi badan, tekanan darah, gula darah, serta konseling gaya hidup. Menurut Profil Kesehatan Provinsi Lampung 2023, terdapat 2.771 Posbindu PTM di Lampung. Selain Posbindu, skrining dapat dilakukan di puskesmas dan melalui program Cek Kesehatan Gratis Kemenkes yang berjalan sejak Februari 2025.

SIGERSEHAT membantu Anda melakukan skrining awal mandiri dan mencatat hasil pengukuran dari Posbindu atau puskesmas agar perkembangannya terpantau. Ingat: hasil skrining bukan diagnosis. Bila hasil Anda berada pada kategori sedang atau tinggi, tindaklanjuti dengan pemeriksaan di fasilitas kesehatan.', 'ptm, skrining, pencegahan', 'active');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status) VALUES
 ('src-germas', 'GERMAS: Gerakan Masyarakat Hidup Sehat', 'Kementerian Kesehatan RI', 'https://kemkes.go.id',
  'GERMAS adalah gerakan yang dicanangkan melalui Instruksi Presiden Nomor 1 Tahun 2017 untuk membudayakan hidup sehat: aktivitas fisik teratur, konsumsi sayur dan buah, tidak merokok, tidak mengonsumsi alkohol, memeriksa kesehatan secara rutin, menjaga kebersihan lingkungan, dan menggunakan jamban sehat.', 'germas, gaya hidup, pencegahan', 'active'),
 ('src-bahaya', 'Tanda Bahaya yang Memerlukan Pertolongan Segera', 'Kementerian Kesehatan RI', 'https://kemkes.go.id',
  'Segera ke IGD atau hubungi 119 bila mengalami: nyeri dada berat atau menjalar, sesak napas berat, kelemahan atau kebas pada satu sisi tubuh, wajah mencong, bicara pelo, pingsan, kejang, atau perdarahan hebat. Kondisi ini adalah keadaan gawat darurat dan tidak boleh menunggu.', 'darurat, tanda bahaya', 'active');
INSERT OR IGNORE INTO edu_quizzes (id, content_id, title, questions_json, status)
VALUES ('quiz-ptm-1', 'art-hipertensi', 'Kuis Hipertensi & PTM', '[{"question_text": "Berapa batas tekanan darah yang termasuk kategori hipertensi?", "options": ["120/80 mmHg", "140/90 mmHg", "100/70 mmHg", "160/110 mmHg"], "correct_index": 1, "explanation": "Hipertensi adalah tekanan darah 140/90 mmHg atau lebih pada pengukuran berulang."}, {"question_text": "Berapa batas konsumsi garam harian yang dianjurkan Kemenkes?", "options": ["3 sendok makan", "1 sendok teh (sekitar 5 gram)", "2 sendok teh", "Tidak ada batas"], "correct_index": 1, "explanation": "Kemenkes menganjurkan garam tidak lebih dari 1 sendok teh (sekitar 5 gram) per hari."}, {"question_text": "Mengapa hipertensi disebut pembunuh senyap?", "options": ["Karena selalu menimbulkan nyeri dada", "Karena umumnya tidak bergejala", "Karena hanya menyerang lansia", "Karena tidak bisa diukur"], "correct_index": 1, "explanation": "Hipertensi umumnya tidak bergejala. Di Lampung, SKI 2023 mencatat kesenjangan terukur 29,7% vs terdiagnosis 7,9%."}, {"question_text": "Berapa lama aktivitas fisik minimal yang dianjurkan setiap hari?", "options": ["5 menit", "15 menit", "30 menit", "2 jam"], "correct_index": 2, "explanation": "Anjuran aktivitas fisik adalah minimal 30 menit setiap hari."}, {"question_text": "Apa yang sebaiknya dilakukan bila hasil skrining menunjukkan kategori risiko tinggi?", "options": ["Mengabaikannya", "Membeli obat sendiri", "Periksa ke fasilitas kesehatan untuk pemeriksaan lanjutan", "Berhenti makan sama sekali"], "correct_index": 2, "explanation": "Hasil skrining risiko tinggi harus ditindaklanjuti dengan pemeriksaan di fasilitas kesehatan. Skrining bukan diagnosis."}]', 'published');
